mapper.update:
UPDATE ${tableName}
SET invoice_amount             = #{model.invoiceAmount},
    remark          = #{model.remark},
    final_approve  = #{model.finalApprove},
    confirm_time   = #{model.confirmTime},
    reject_reason   = #{model.rejectReason},
    reject_time     = #{model.rejectTime},
    approval_status = #{model.approvalStatus}
WHERE primary_key = #{model.recordCode}
  AND enterprise_code = #{model.enterpriseCode}

