mapper.select:
SELECT record.primary_key, record.applicant, record.apply_time, record.invoice_type, record.invoice_amount, record.remark, record.final_approve, record.confirm_time, record.reject_reason, record.reject_time, record.approval_status, record.signed_contract, record.record_batch, record.contract_number, record.enterprise_code, contract.counterpart AS opposite FROM ${invoiceTableName} record LEFT JOIN ${signedContractTable} contract ON record.signed_contract = contract.primary_key WHERE record.enterprise_code = #{enterpriseCode} AND record.delete_flag = 'f' AND record.approval_status != 'WITHDRAWN'
AND contract.counterpart LIKE '%'|| #{opposite} ||'%'
AND record.contract_number LIKE '%'|| #{contractNumber} ||'%'
AND contract.user_code IN
#{userCode}
AND record.applicant IN
#{applicant}
AND record.approval_status IN
#{approveState}
AND record.apply_time IS NOT NULL AND record.apply_time >= #{applyTimePre}
AND record.apply_time IS NOT NULL AND record.apply_time <= #{applyTimePost}
ORDER BY record.id DESC
